
import React from 'react';

const Grain: React.FC = () => {
  const grainStyle: React.CSSProperties = {
    position: 'fixed',
    top: 0,
    left: 0,
    width: '100vw',
    height: '100vh',
    backgroundImage: `url('data:image/svg+xml;base64,')`,
    pointerEvents: 'none',
    zIndex: 10,
    opacity: 0.07, // Base opacity for animation
  };

  return <div style={grainStyle} className="animate-grain-flicker"></div>;
};

export default Grain;